-- OTOTR Finance migration promoted from a reviewed candidate.
-- Source: candidate-fee-rule-discard-rpc.sql
-- Source SHA256: 5A5D34275F1346CBE61882D8BD940B7AC90C5119DE71B3D9E948DC4F58A3EF4A
-- Local replay required before any staging promotion.
-- OTOTR CONTRACT FEE RULE DISCARD RPC CANDIDATE
create or replace function finance_private.current_fee_rule_discard_committer_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_fee_rule_discard_scope(p_actor_id uuid,p_contract_version_id uuid,p_fee_rule_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
create or replace function finance_api.authorize_fee_rule_discard(p_contract_version_id uuid,p_fee_rule_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select case when auth.uid() is null or p_permission<>'finance.fee-rules.discard' then null::jsonb else finance_private.resolve_fee_rule_discard_scope(auth.uid(),p_contract_version_id,p_fee_rule_id,p_permission) end$$;
create or replace function finance_api.commit_fee_rule_discard(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_contract_version_id uuid,p_fee_rule_id uuid,p_expected_version bigint,p_reversal_date date,p_reason_code text,p_note_hash text,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare r record;v_existing record;v_new bigint;v_payload jsonb;v_previous text;v_audit text;
begin
 if not finance_private.current_fee_rule_discard_committer_is_trusted() then raise exception using errcode='42501',message='trusted fee rule discard committer required';end if;
 if p_expected_version<1 or p_reversal_date is null or pg_catalog.length(pg_catalog.btrim(coalesce(p_reason_code,''))) not between 1 and 100 or (p_note_hash is not null and p_note_hash!~'^[a-fA-F0-9]{64}$') or pg_catalog.length(pg_catalog.btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' then raise exception using errcode='22023',message='invalid fee rule discard command';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('fee-rule-discard:'||p_fee_rule_id::text||':'||p_idempotency_key,0));
 select om.payload into v_existing from finance.outbox_messages om where om.legal_entity_id=p_legal_entity_id and om.event_type='CONTRACT_FEE_RULE_DRAFT_DISABLED' and om.aggregate_id=p_fee_rule_id and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;if found then if v_existing.payload->>'intentHash'=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','feeRuleId',p_fee_rule_id,'status','DISABLED','version',(v_existing.payload->>'version')::bigint);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 select cfr.*,cv.status contract_version_status,fc.legal_entity_id,fc.dealer_legal_entity_id,fc.status contract_status into r from finance.contract_fee_rules cfr join finance.contract_versions cv on cv.id=cfr.contract_version_id join finance.franchise_contracts fc on fc.id=cv.contract_id where cfr.id=p_fee_rule_id and cfr.contract_version_id=p_contract_version_id for update of cfr,cv,fc;if not found then raise exception using errcode='P0002',message='fee rule not found';end if;
 if r.legal_entity_id<>p_legal_entity_id or r.dealer_legal_entity_id<>p_dealer_legal_entity_id or r.status<>'DRAFT' or r.contract_version_status<>'DRAFT' or r.contract_status in ('TERMINATED','DISCARDED') or r.version<>p_expected_version then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if not exists(select 1 from finance.dealer_accounts da join finance.branches b on b.legal_entity_id=da.legal_entity_id and b.dealer_legal_entity_id=da.dealer_legal_entity_id where da.id=p_dealer_account_id and da.legal_entity_id=p_legal_entity_id and da.dealer_legal_entity_id=p_dealer_legal_entity_id and b.id=p_branch_id) then raise exception using errcode='42501',message='fee rule discard three dimensional scope denied';end if;
 if exists(select 1 from finance.calculation_runs cr where cr.contract_fee_rule_id=p_fee_rule_id) or exists(select 1 from finance.rule_exceptions re where re.contract_fee_rule_id=p_fee_rule_id and re.status not in ('DISABLED','SUPERSEDED')) then raise exception using errcode='23514',message='used or exception-bearing fee rule cannot be discarded';end if;
 v_new:=r.version+1;update finance.contract_fee_rules set status='DISABLED',version=v_new,correlation_id=p_correlation_id where id=p_fee_rule_id and version=p_expected_version and status='DRAFT';if not found then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 v_payload:=pg_catalog.jsonb_build_object('feeRuleId',p_fee_rule_id,'contractVersionId',p_contract_version_id,'feeDefinitionId',r.fee_definition_id,'ruleCode',r.rule_code,'status','DISABLED','version',v_new,'reversalDate',p_reversal_date,'reasonCode',p_reason_code,'noteHash',p_note_hash,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.contract','CONTRACT_FEE_RULE_DRAFT_DISABLED','CONTRACT_FEE_RULE',p_fee_rule_id,v_new,v_payload,p_intent_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select integrity_hash into v_previous from finance.audit_events where legal_entity_id=p_legal_entity_id order by created_at_utc desc,id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||p_fee_rule_id::text||':CONTRACT_FEE_RULE_DRAFT_DISABLED:'||p_intent_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,reason_code,before_hash,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','CONTRACT_FEE_RULE_DRAFT_DISABLED','CONTRACT_FEE_RULE',p_fee_rule_id,'ALLOW',p_reason_code,r.correlation_id::text,p_intent_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('contractVersionId',p_contract_version_id,'feeDefinitionId',r.fee_definition_id,'ruleCode',r.rule_code,'branchId',p_branch_id,'reversalDate',p_reversal_date,'noteHash',p_note_hash,'previousVersion',r.version),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','DISCARDED','feeRuleId',p_fee_rule_id,'status','DISABLED','version',v_new);
end$$;
revoke all on function finance_private.current_fee_rule_discard_committer_is_trusted() from public,anon,authenticated;revoke all on function finance_private.resolve_fee_rule_discard_scope(uuid,uuid,uuid,text) from public,anon,authenticated;revoke all on function finance_api.authorize_fee_rule_discard(uuid,uuid,text) from public,anon;grant execute on function finance_api.authorize_fee_rule_discard(uuid,uuid,text) to authenticated;revoke all on function finance_api.commit_fee_rule_discard(uuid,uuid,uuid,uuid,uuid,uuid,uuid,bigint,date,text,text,text,text,uuid) from public,anon,authenticated;
